CREATE OR REPLACE FUNCTION public.fn_accounting_union_earned_plan_combine(p_union_id uuid, p_start timestamp with time zone, p_end timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE n_expected bigint; n_have bigint; bank numeric; src numeric; house numeric; fp text; detail jsonb;
BEGIN
 IF COALESCE(current_setting('app.weekly_accounting_chunked',true),'')<>'on'
  OR current_setting('app.accounting_close_memo',true) IS DISTINCT FROM 'on'
  OR p_union_id IS NULL OR p_start IS NULL OR p_end IS NULL OR NOT isfinite(p_start) OR NOT isfinite(p_end) OR p_start>=p_end
  OR p_end>clock_timestamp()
  OR NOT EXISTS(SELECT 1 FROM public.accounting_cash_accrual_cutover WHERE singleton AND starts_at<=p_start) THEN
  RETURN NULL;
 END IF;
 CREATE TEMP TABLE IF NOT EXISTS _close_plan_windows(window_start timestamptz PRIMARY KEY,value jsonb,cash_ids uuid[],cash_md5 bytea,fee_ids uuid[],fee_md5 bytea) ON COMMIT DROP;
 TRUNCATE pg_temp._close_plan_windows;
 INSERT INTO pg_temp._close_plan_windows SELECT p.window_start,p.value,p.cash_ids,p.cash_md5,p.fee_ids,p.fee_md5
  FROM public.fn_accounting_close_windows(p_start,p_end) w JOIN public.accounting_close_partials p
   ON p.kind='earned_plan_window' AND p.union_id=p_union_id AND p.period_start=p_start AND p.period_end=p_end
   AND p.window_start=w.window_start AND p.window_end=w.window_end
   AND p.computed_at>=p_end AND p.computed_at>clock_timestamp()-public.fn_accounting_close_proof_lifetime();
 GET DIAGNOSTICS n_have=ROW_COUNT;
 SELECT count(*) INTO n_expected FROM public.fn_accounting_close_windows(p_start,p_end);
 IF n_have<>n_expected OR n_expected=0 THEN RETURN NULL; END IF;
 SELECT COALESCE(sum((value->>'bank_sum')::numeric),0),COALESCE(sum((value->>'source_sum')::numeric),0),
  COALESCE(sum((value->>'house_sum')::numeric),0) INTO bank,src,house FROM pg_temp._close_plan_windows;
 -- Every window passed the six source proofs, so the set path (and v3) would
 -- reach exactly this conservation test of the week, and refuse as v3 does.
 IF src IS DISTINCT FROM bank THEN RAISE EXCEPTION 'union_earned_rake_does_not_conserve_bank' USING ERRCODE='55000'; END IF;
 -- The set path's fingerprint: md5 of every source's row md5 in (source_type,
 -- source_id) order; every cash_rake_accrual sorts before every
 -- tournament_fee_accrual.
 WITH fingerprint_windows AS MATERIALIZED (SELECT w.cash_ids,w.cash_md5||''::bytea AS cash_md5,w.fee_ids,w.fee_md5||''::bytea AS fee_md5 FROM pg_temp._close_plan_windows w),
 cash_rows AS MATERIALIZED (SELECT u.id,encode(substring(w.cash_md5 FROM (u.ord::int-1)*16+1 FOR 16),'hex') AS row_md5 FROM fingerprint_windows w CROSS JOIN LATERAL unnest(w.cash_ids) WITH ORDINALITY u(id,ord)),
 fee_rows AS MATERIALIZED (SELECT u.id,encode(substring(w.fee_md5 FROM (u.ord::int-1)*16+1 FOR 16),'hex') AS row_md5 FROM fingerprint_windows w CROSS JOIN LATERAL unnest(w.fee_ids) WITH ORDINALITY u(id,ord))
 SELECT md5(COALESCE((SELECT string_agg(c.row_md5,'' ORDER BY c.id) FROM cash_rows c),'')
  ||COALESCE((SELECT string_agg(f.row_md5,'' ORDER BY f.id) FROM fee_rows f),'')) INTO fp;
 SELECT COALESCE(jsonb_agg(to_jsonb(b) ORDER BY club_id,game_type),'[]') INTO detail FROM (
  SELECT (e->>'club_id')::uuid AS club_id,e->>'game_type' AS game_type,sum((e->>'rake_in')::numeric) AS rake_in,
   CASE WHEN sum((e->>'rake_in')::numeric)>0 THEN sum((e->>'weighted')::numeric)/sum((e->>'rake_in')::numeric) ELSE 0 END AS rate,
   trunc(sum((e->>'weighted')::numeric),2) AS payout
   FROM pg_temp._close_plan_windows w CROSS JOIN LATERAL jsonb_array_elements(w.value->'basis') e
   GROUP BY (e->>'club_id')::uuid,e->>'game_type') b;
 RETURN jsonb_build_object('accounting_version',3,'union_id',p_union_id,'period_start',p_start,'period_end',p_end,
  'period_rake',bank,'earned_rake',src,'house_rake',house,'source_fingerprint',fp,'basis_detail',detail);
END $function$

CREATE OR REPLACE FUNCTION public.fn_accounting_union_earned_plan(p_union_id uuid, p_start timestamp with time zone, p_end timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
-- WEEKLY CLOSE SCALE (20260928): a union's weekly close proves the same earned
-- plan up to nine times in one transaction (preparation twice, round 1 twice,
-- round 3, the ECO gate and the invoice evidence), about a minute each at
-- Midway's scale. Inside a close (app.accounting_close_memo='on', set only by
-- fn_process_weekly_accounting_scope for the attempt it is running) the first
-- proof of a (union, week) is kept for the rest of that transaction; a
-- rolled-back attempt forgets it with its subtransaction. Everywhere else the
-- plan is proved on every call, exactly as before, by
-- fn_accounting_union_earned_plan_v3.
DECLARE memo jsonb; memo_key text; plan jsonb;
BEGIN
 IF current_setting('app.accounting_close_memo',true)='on' THEN
  memo_key:=p_union_id::text||'|'||p_start::text||'|'||p_end::text;
  memo:=NULLIF(current_setting('app.accounting_earned_plan_memo',true),'')::jsonb;
  IF memo ? memo_key THEN RETURN memo->memo_key; END IF;
 END IF;
 -- CHUNKED CLOSE CERTIFICATE (20261003): inside a chunked union close attempt a
 -- plan proved by an earlier attempt of this close is answered from
 -- accounting_close_certificates; one proved here is kept there. Off
 -- everywhere else (fn_accounting_close_certificate returns NULL).
 plan:=public.fn_accounting_close_certificate('earned_plan',p_union_id,p_start,p_end);
 IF plan IS NULL THEN
 -- 20261003: the set path certifies the identical plan; anything it does
 -- not certify is proved (and refused) by v3 exactly as before.
 -- CHUNKED CLOSE WINDOWS (20261003): inside a chunked close the plan is
 -- combined from its proved two-hour windows; NULL everywhere else and
 -- while any window is missing, when the set path runs as before.
 plan:=public.fn_accounting_union_earned_plan_combine(p_union_id,p_start,p_end);
 IF plan IS NULL THEN
 plan:=public.fn_accounting_union_earned_plan_sets(p_union_id,p_start,p_end);
 END IF;
 IF plan IS NULL THEN plan:=public.fn_accounting_union_earned_plan_v3(p_union_id,p_start,p_end); END IF;
  PERFORM public.fn_accounting_close_certify('earned_plan',p_union_id,p_start,p_end,plan);
 END IF;
 IF memo_key IS NOT NULL THEN
  PERFORM set_config('app.accounting_earned_plan_memo',(COALESCE(memo,'{}'::jsonb)||jsonb_build_object(memo_key,plan))::text,true);
 END IF;
 RETURN plan;
END $function$

CREATE OR REPLACE FUNCTION public.fn_credit_treasury_zd4core(p_club_id uuid, p_amount numeric, p_reason text, p_metadata jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_before numeric;
  v_after numeric;
BEGIN
  IF p_club_id IS NULL OR p_amount IS NULL OR p_amount <= 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'invalid parameters');
  END IF;

  /* THE CALLER NAMES WHERE THE CHIPS COME FROM (2026-10-02,
     20261002140203). fn_union_weekly_rakeback_close and
     fn_accounting_legacy_pay_week declare and stand the clubs journal down;
     a caller that does neither would be refused at commit. Say so here, by
     name, before anything moves. */
  IF NULLIF(current_setting('app.ledger_counterparty', true), '') IS NULL
     AND COALESCE(current_setting('app.ledger_autoskip_clubs', true), '') <> '1' THEN
    RAISE EXCEPTION 'fn_credit_treasury_requires_a_declared_counterparty'
      USING ERRCODE = '23514',
            DETAIL  = 'a club treasury credit with no app.ledger_counterparty would be journalled against settlement_suspense',
            HINT    = 'The calling door declares where the chips come from (fn_ca_declare_ledger), or stands the clubs journal down and writes its own leg.';
  END IF;

  SELECT COALESCE(chip_treasury, 0) INTO v_before
  FROM clubs WHERE id = p_club_id FOR NO KEY UPDATE;

  IF v_before IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'club not found');
  END IF;

  UPDATE clubs
  SET chip_treasury = COALESCE(chip_treasury, 0) + p_amount,
      updated_at = NOW()
  WHERE id = p_club_id;
  v_after := v_before + p_amount;

  INSERT INTO chip_transactions (
    id, club_id, amount, transaction_type, notes, metadata, balance_after, created_at
  ) VALUES (
    gen_random_uuid(), p_club_id, p_amount,
    'treasury_credit', COALESCE(p_reason, 'Treasury credit'), p_metadata, v_after, NOW()
  );

  RETURN jsonb_build_object(
    'success', true,
    'amount', p_amount,
    'balance_before', v_before,
    'balance_after', v_after
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_credit_treasury(p_club_id uuid, p_amount numeric, p_reason text DEFAULT NULL::text, p_metadata jsonb DEFAULT '{}'::jsonb, p_op_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_prior jsonb;
  v_res jsonb;
BEGIN
  IF p_op_id IS NULL THEN
    RETURN public.fn_credit_treasury_zd4core(p_club_id, p_amount, p_reason, p_metadata);
  END IF;

  SELECT result INTO v_prior
    FROM public.ca_op_claims
   WHERE op_id = p_op_id AND fn_name = 'fn_credit_treasury';
  IF FOUND AND v_prior IS NOT NULL THEN
    RETURN v_prior || jsonb_build_object('replayed', true, 'op_id', p_op_id);
  ELSIF FOUND THEN
    DELETE FROM public.ca_op_claims
     WHERE op_id = p_op_id AND fn_name = 'fn_credit_treasury';
  END IF;

  INSERT INTO public.ca_op_claims (op_id, fn_name, claimed_by)
  VALUES (p_op_id, 'fn_credit_treasury', auth.uid());

  v_res := public.fn_credit_treasury_zd4core(p_club_id, p_amount, p_reason, p_metadata);

  IF COALESCE(v_res->>'success', '') = 'true' THEN
    UPDATE public.ca_op_claims
       SET result = v_res, finalized_at = now()
     WHERE op_id = p_op_id AND fn_name = 'fn_credit_treasury';
  ELSE
    DELETE FROM public.ca_op_claims
     WHERE op_id = p_op_id AND fn_name = 'fn_credit_treasury';
  END IF;

  RETURN v_res;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_union_pnl_closed_book_barrier(p_at timestamp with time zone)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE started timestamptz; book timestamptz;
BEGIN
 IF p_at IS NULL OR NOT isfinite(p_at) OR p_at<>public.fn_union_week_start(p_at) OR p_at>clock_timestamp()
  OR current_setting('transaction_isolation')<>'read committed' THEN
  RAISE EXCEPTION 'closed_original_book_barrier_required' USING ERRCODE='22023'; END IF;
 SELECT captured_at INTO started FROM public.union_pnl_inventory_capture WHERE singleton;
 IF started IS NULL THEN RAISE EXCEPTION 'original_inventory_capture_missing' USING ERRCODE='55000'; END IF;
 book:=public.fn_union_week_start(started);
 WHILE book<p_at LOOP
  PERFORM pg_advisory_xact_lock(hashtextextended('union-pnl-inventory:'||extract(epoch FROM book)::bigint::text,0));
  book:=public.fn_union_week_start(book+interval '8 days');
 END LOOP;
END $function$
